class Solution {
  public long goodTriplets(int[] nums1, int[] nums2) {
    int n = nums1.length;
    int[] pos = new int[n];
    for (int i = 0; i < n; i++) pos[nums2[i]] = i;
    int[] tree = new int[n + 1];
    long answer = 0;
    for (int i = 0; i < n; i++) {
      int p = pos[nums1[i]];
      // smaller: earlier in nums1 and earlier in nums2; larger: later in both
      long smaller = 0;
      for (int j = p; j > 0; j -= j & -j) smaller += tree[j];
      long larger = (n - 1 - p) - (i - smaller);
      answer += smaller * larger;
      for (int j = p + 1; j <= n; j += j & -j) tree[j]++;
    }
    return answer;
  }
}
